func:
// Zweck: Verarbeitet eine Status-Meldung eines Master-Geräts (Gateway).
// Eingaben: msg.sh (Routing-State), msg.payload mit online, wifi, mqtt, espnow, fw.
// Ergebnis: msg.payload mit aktualisiertem Master-Objekt, msg.sqlite_batch für die Persistenzschicht.
// Seiteneffekt: Schreibt das aktualisierte Master-Objekt in smarthome_runtime (global).
const topicHandlers = global.get("topicHandlers");
const result = topicHandlers.handleRoutedMessage(global.get("smarthome_runtime"), msg.sh, msg.payload);
if (!result || !result.payload || !result.payload.master) {
    node.warn("master status without master_id");
    return null;
}
global.set("smarthome_runtime", result.runtime);
msg.payload = result.payload;
msg.sqlite_batch = result.sqlite_batch || null;
return msg;
